44: .pause-pill{position:absolute;z-index:4;top:56px;right:clamp(18px,4vw,56px);border:1px solid #ffffff38;background:#091817b8;border-radius:4px;padding:8px 11px;font-size:9px;font-weight:900;letter-spacing:.16em;pointer-events:auto;visibility:hidden}
