77: .sm-body{display:flex;justify-content:flex-end;align-items:flex-end;gap:5px}
78: .sm-caption{writing-mode:vertical-rl;text-orientation:mixed;font-size:7px;font-weight:900;letter-spacing:.2em;color:#c9d6c8;transform:rotate(180deg);text-shadow:0 2px 4px #000}
79: .sm-track{position:relative;width:11px;height:118px;border-radius:6px;border:1px solid #e9f2df8f;background:#071313d9;box-shadow:0 0 12px #000a;overflow:visible}
