81: .sm-window{position:absolute;left:-4px;right:-4px;background:#d8ff3e2e;border-top:1px solid #efffd0;border-bottom:1px solid #efffd0;box-shadow:0 0 12px #d8ff3e55}
82: .sm-label{margin-top:4px;text-align:center;font-size:7px;font-weight:950;letter-spacing:.12em;color:#dfe8db;text-shadow:0 2px 4px #000}
