564: const topR = 0.225, botR = 0.14;
565: for (let s = 0; s < strands; s++) {
566:   const a0 = (s / strands) * Math.PI * 2;
567:   for (let r = 0; r < netRings; r++) {
568:     const t0 = r / netRings, t1 = (r + 1) / netRings;
569:     const r0 = topR + (botR - topR) * t0;
