1929:     base - contest * 0.27 - Math.max(0, d - 6.75) * 0.034 - Math.max(0, d - 8.5) * 0.02 - Math.min(0.16, moving * 0.022)
1930:   ));
1931:   const made = green || Math.random() < chance;
